package cn.huankan.event;
import java.util.*;
import java.nio.charset.StandardCharsets;
import cn.huankan.evidence.EvidenceService;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service public class GovernanceService {
 private final JdbcTemplate db;private final ObjectMapper json;public GovernanceService(JdbcTemplate db,ObjectMapper json){this.db=db;this.json=json;}
 private String encode(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalArgumentException("研究数据编码失败");}}
 public Object rules(){return db.queryForList("SELECT * FROM financial_topic_rule ORDER BY id");}
 @Transactional public Object configure(String id,List<String> terms,int weight,String reason){if(terms==null||terms.isEmpty()||terms.size()>100||terms.stream().anyMatch(s->s==null||s.isBlank()||s.length()>100)||weight<0||weight>40||reason==null||reason.length()<10||reason.length()>2000)throw new IllegalArgumentException("分类规则或审核依据无效");var old=db.queryForMap("SELECT * FROM financial_topic_rule WHERE id=? FOR UPDATE",id);db.update("UPDATE financial_topic_rule SET terms=?::jsonb,weight=?,version=version+1 WHERE id=?",encode(terms),weight,id);db.update("INSERT INTO governance_rule_audit(rule_id,old_value,new_value,reason) VALUES(?,?::jsonb,?::jsonb,?)",id,encode(old),encode(Map.of("terms",terms,"weight",weight)),reason);return Map.of("message","规则已更新，需分批重新治理");}
 @Transactional public Object process(int limit){if(limit<1||limit>1000)throw new IllegalArgumentException("处理批次无效");db.execute("SELECT pg_advisory_xact_lock(742024)");var rules=db.queryForList("SELECT * FROM financial_topic_rule WHERE enabled ORDER BY id");String version="可配置治理-1.1:"+EvidenceService.hash(encode(rules).getBytes(StandardCharsets.UTF_8));var rows=db.queryForList("SELECT e.*,s.level,r.source_url,r.published_at,d.underlying_url,d.themes FROM financial_event e JOIN raw_evidence r ON r.id=e.evidence_id JOIN source_registry s ON s.id=e.source_id LEFT JOIN aggregated_dependency d ON d.evidence_id=r.id LEFT JOIN governed_message g ON g.event_id=e.id WHERE e.source_id NOT IN('ECB_DATA','FRED') AND (g.event_id IS NULL OR g.evidence_id<>e.evidence_id OR g.rule_version<>?) ORDER BY e.id LIMIT ?",version,limit);
  for(var row:rows){String title=row.get("original_title").toString(),input=(title+" "+Objects.toString(row.get("themes"),"").replace('_',' ')).toLowerCase(Locale.ROOT);var topics=new ArrayList<String>();var hits=new LinkedHashMap<String,Object>();int score="L0".equals(row.get("level"))?30:0;
   for(var rule:rules){try{var terms=json.readValue(rule.get("terms").toString(),String[].class);var matched=Arrays.stream(terms).filter(x->matches(input,x.toLowerCase(Locale.ROOT))).toList();if(!matched.isEmpty()){topics.add(rule.get("display_name_zh").toString());score+=((Number)rule.get("weight")).intValue();hits.put(rule.get("id").toString(),matched);}}catch(Exception e){throw new IllegalArgumentException("分类规则无法读取");}}
   var basis=Map.of("来源优先",row.get("level"),"命中词",hits,"未提供因素",List.of("市场预期","已核实跨市场影响","未经来源核实的变化幅度"),"说明","规则优先级不代表事实核实或投资收益预测");db.update("INSERT INTO governed_message(event_id,evidence_id,topics,priority,basis,rule_version) VALUES(?,?,?::jsonb,?,?::jsonb,?) ON CONFLICT(event_id) DO UPDATE SET evidence_id=excluded.evidence_id,topics=excluded.topics,priority=excluded.priority,basis=excluded.basis,rule_version=excluded.rule_version,processed_at=now()",row.get("id"),row.get("evidence_id"),encode(topics),Math.min(score,100),encode(basis),version);
   if(topics.isEmpty())continue;String key;String dependency;try{Object original=row.get("underlying_url");key=ResearchRules.canonical((original==null?row.get("source_url"):original).toString());dependency="同一原文URL；保留所有记录，不证明独立经济事实相同";}catch(Exception e){key=row.get("id").toString();dependency="原文URL未知，独立候选";}
   String hash=EvidenceService.hash(key.getBytes(StandardCharsets.UTF_8));UUID caseId=UUID.randomUUID();db.update("INSERT INTO research_case(id,title,cluster_key,cluster_method) VALUES(?,?,?,'ARTICLE_URL') ON CONFLICT(cluster_key) DO NOTHING",caseId,title,hash);caseId=db.queryForObject("SELECT id FROM research_case WHERE cluster_key=?",UUID.class,hash);db.update("INSERT INTO research_case_message VALUES(?,?,?) ON CONFLICT DO NOTHING",caseId,row.get("id"),dependency);
  }return Map.of("processed",rows.size(),"rule_version",version);}
 static boolean matches(String input,String term){return term.chars().allMatch(c->c<128)?java.util.regex.Pattern.compile("(?<![a-z])"+java.util.regex.Pattern.quote(term)+"(?![a-z])").matcher(input).find():input.contains(term);}
 public Object cases(int page){if(page<0||page>100000)throw new IllegalArgumentException("页码无效");return db.queryForList("SELECT c.*,count(m.event_id) message_count,max(g.priority) priority FROM research_case c JOIN research_case_message m ON m.case_id=c.id JOIN governed_message g ON g.event_id=m.event_id GROUP BY c.id ORDER BY max(g.priority) DESC,c.id LIMIT 50 OFFSET ?",page*50);}
 public Object detail(UUID id){return Map.of("case",db.queryForMap("SELECT * FROM research_case WHERE id=?",id),"messages",db.queryForList("SELECT m.*,e.evidence_id,e.original_title,r.source_url,r.published_at,r.raw_content_hash,g.topics,g.basis FROM research_case_message m JOIN financial_event e ON e.id=m.event_id JOIN raw_evidence r ON r.id=e.evidence_id JOIN governed_message g ON g.event_id=e.id WHERE m.case_id=? LIMIT 100",id),"facts",db.queryForList("SELECT * FROM research_case_fact WHERE case_id=? LIMIT 100",id),"hypotheses",db.queryForList("SELECT * FROM research_hypothesis WHERE case_id=? LIMIT 100",id),"links",db.queryForList("SELECT * FROM research_case_link WHERE left_case_id=? OR right_case_id=? LIMIT 100",id,id));}
 public record Fact(UUID evidenceId,String claim,String excerpt){}
 @Transactional public UUID fact(UUID caseId,Fact f){
  if(f.evidenceId()==null||f.claim()==null||f.claim().isBlank()||f.claim().length()>4000||f.excerpt()==null||f.excerpt().length()<5||f.excerpt().length()>4000)throw new IllegalArgumentException("事实与逐字摘录无效");
  var row=db.queryForMap("SELECT r.raw_content,r.raw_content_hash FROM research_case_message m JOIN financial_event e ON e.id=m.event_id JOIN raw_evidence r ON r.id=e.evidence_id WHERE m.case_id=? AND r.id=? LIMIT 1",caseId,f.evidenceId());byte[] bytes=(byte[])row.get("raw_content");String full=new String(bytes,StandardCharsets.UTF_8);int at=full.indexOf(f.excerpt());
  if(at<0||!EvidenceService.hash(bytes).equals(row.get("raw_content_hash")))throw new IllegalArgumentException("摘录不是本候选事件的完整真实证据");UUID id=UUID.randomUUID();int start=full.codePointCount(0,at),end=start+f.excerpt().codePointCount(0,f.excerpt().length());
  db.update("INSERT INTO research_case_fact(id,case_id,claim,evidence_id,excerpt,start_offset,end_offset) VALUES(?,?,?,?,?,?,?)",id,caseId,f.claim(),f.evidenceId(),f.excerpt(),start,end);return id;
 }
 @Transactional public void reviewFact(UUID factId,String decision,String reason,String actor){
  if(!Set.of("VERIFIED","CONFLICT","REJECTED").contains(decision)||reason==null||reason.length()<10||reason.length()>4000||actor==null||actor.isBlank()||actor.length()>200)throw new IllegalArgumentException("审核决定、理由或审核人无效");
  UUID caseId=db.queryForObject("SELECT case_id FROM research_case_fact WHERE id=? FOR UPDATE",UUID.class,factId);db.update("UPDATE research_case_fact SET status=? WHERE id=?",decision,factId);db.update("INSERT INTO case_review(case_id,fact_id,decision,reason,actor) VALUES(?,?,?,?,?)",caseId,factId,decision,reason,actor);
  db.update("UPDATE research_case SET verification=CASE WHEN EXISTS(SELECT 1 FROM research_case_fact WHERE case_id=? AND status='CONFLICT') THEN 'CONFLICT' ELSE 'PENDING' END WHERE id=?",caseId,caseId);
 }
 public record Hypothesis(String mechanism,String direction,List<UUID> evidenceIds,String uncertainty){}
 @Transactional public UUID hypothesis(UUID caseId,Hypothesis h){if(h.mechanism()==null||h.mechanism().length()<10||h.mechanism().length()>4000||!Set.of("POSITIVE","NEGATIVE","UNCERTAIN").contains(h.direction())||h.uncertainty()==null||h.uncertainty().length()<5||h.uncertainty().length()>4000||h.evidenceIds()==null||h.evidenceIds().isEmpty()||h.evidenceIds().size()>20)throw new IllegalArgumentException("影响假设缺少机制、证据或不确定性");
  for(UUID id:h.evidenceIds())if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM research_case_message m JOIN financial_event e ON e.id=m.event_id WHERE m.case_id=? AND e.evidence_id=?)",Boolean.class,caseId,id)))throw new IllegalArgumentException("假设引用不属于本候选事件的证据");UUID id=UUID.randomUUID();db.update("INSERT INTO research_hypothesis(id,case_id,mechanism,direction,generated_by,evidence_ids,uncertainty) VALUES(?,?,?,?,'MANUAL',string_to_array(?,',')::uuid[],?)",id,caseId,h.mechanism(),h.direction(),h.evidenceIds().stream().map(UUID::toString).collect(java.util.stream.Collectors.joining(",")),h.uncertainty());return id;
 }
 public record Link(UUID otherCaseId,String kind,UUID evidenceId,String excerpt,String reason){}
 @Transactional public UUID link(UUID caseId,Link l){if(l.otherCaseId()==null||caseId.equals(l.otherCaseId())||l.kind()==null||!Set.of("POTENTIAL_SAME_FACT","FOLLOW_UP","RELATED","CONFLICT").contains(l.kind())||l.reason()==null||l.reason().length()<10||l.excerpt()==null||l.excerpt().length()<10||l.excerpt().length()>4000)throw new IllegalArgumentException("候选关联依据不足");String raw=new String(db.queryForObject("SELECT raw_content FROM raw_evidence WHERE id=?",byte[].class,l.evidenceId()),StandardCharsets.UTF_8);if(!raw.contains(l.excerpt()))throw new IllegalArgumentException("关联摘录不在真实证据中");UUID id=UUID.randomUUID();db.update("INSERT INTO research_case_link(id,left_case_id,right_case_id,kind,evidence_id,excerpt,reason) VALUES(?,?,?,?,?,?,?)",id,caseId,l.otherCaseId(),l.kind(),l.evidenceId(),l.excerpt(),l.reason());return id;}
}
